"""Read-only 1078-column authority and pre-optimize computation policy."""
from .common import *
def prepare():
    import numpy as np,gurobipy as gp
    from v42_dw_root.models import hash_column
    assert subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip()==BASE_HEAD
    assert not (OUT/'DW_THROUGHPUT_PREREGISTRATION.json').exists()
    for folder in ('logs','pricing_points','pricing_receipts','columns','bound_certificates','warm_cold'):(OUT/folder).mkdir(parents=True,exist_ok=True)
    tracked=subprocess.check_output(['git','ls-files','-z'],cwd=ROOT).decode().split('\0')
    write('PR141_BYTE_FREEZE.json',dict(head=BASE_HEAD,files=[dict(path=p,sha256=sha(ROOT/p)) for p in tracked if p]))
    checkpoint=read(POLICY/'DW_POLICY_CHECKPOINT_LATEST.json');assert checkpoint['total_retained_columns']==len(checkpoint['pool'])==1078
    final=read(POLICY/'DW_POLICY_CANARY_FINAL.json');assert final['retained_columns']==1078 and final['new_discovery_columns']==12
    checks=[];seen=[set() for _ in UNITS]
    for directory,h in old_columns():
        p=directory/h['file'];assert sha(p)==h['file_SHA']
        with np.load(p) as z:
            new='x' in z;x=z['x'] if new else z['local_values'];a=z['a'] if new else z['master_coefficients'];c=float(z['c'] if new else z['objective'])
            assert hash_column(x,a,c)==h['SHA256'];m=UNITS.index(h['MESS']);assert h['SHA256'] not in seen[m];seen[m].add(h['SHA256'])
        checks.append(dict(MESS=h['MESS'],file=p.relative_to(ROOT).as_posix(),file_SHA=h['file_SHA'],column_SHA=h['SHA256'],PASS=True))
    assert len(checks)==1078
    write('DW_THROUGHPUT_BASE_AUDIT.json',dict(PASS=True,PR141_head=BASE_HEAD,checkpoint_file='docs/v42_m1_dw_discovery_certification_policy/DW_POLICY_CHECKPOINT_LATEST.json',checkpoint_SHA=sha(POLICY/'DW_POLICY_CHECKPOINT_LATEST.json'),total_retained_columns=1078,initial_columns=4,PR140_generated_columns=1044,PR140_bound_added=18,PR141_added=12,checks=checks,old_TIME_LIMIT_retroactively_promoted=False,interrupted_uncertified_points_promoted=False,old_independent_verification_SHA=sha(POLICY/'VERIFICATION.json'),previous_best_interval=final['final_interval']))
    m=gp.Model();params={p:[str(t) if isinstance(t,type) else t for t in m.getParamInfo(p)] for p in ('Method','LPWarmStart','Presolve','Threads')};version=list(gp.gurobi.version());m.dispose()
    logs=list((POLICY/'logs').glob('RMP_*.log'));discard=[p.relative_to(ROOT).as_posix() for p in logs if 'discard basis' in p.read_text(encoding='utf8',errors='replace')]
    write('DW_RMP_BASIS_REUSE_AUDIT.json',dict(Gurobi_version=version,runtime_parameter_introspection=params,old_basis_discard_logs=discard,diagnosis='PR141 explicitly supplies VBasis/CBasis but keeps Method=2 and default LPWarmStart; native barrier discards the basis. An unchanged-model cached optimize is not basis-acceptance evidence. Appended lambdas preserve all rows and old variable order; initialize their lower-bound nonbasic VBasis=-1.',candidate=dict(Method=1,LPWarmStart=2,Presolve=-1,Threads=1),candidate_semantics='Documented dual simplex; derive primal/dual start vectors from supplied complete basis, crush to presolved model, refine presolved simplex start.',documentation=['https://docs.gurobi.com/projects/optimizer/en/current/reference/parameters.html#lpwarmstart','https://docs.gurobi.com/projects/optimizer/en/current/reference/attributes/variable.html#vbasis'],parameter_sweep=False))
    write('DW_RESOURCE_POLICY_V2.json',dict(available_RAM_floor_bytes=1024**3,RAM_GATE_GIB=1,old_8_GiB_15_percent_gate_superseded=True,commit_stop_percent=95,sustained_thrashing=dict(window_seconds=10,min_samples=11,pagefile_increase_bytes=256*1024**2,every_hard_page_input_sample_at_least_pages_per_second=1000,conjunction_required=True),paging_counter='PDH English Memory Pages Input/sec; pages loaded for hard faults, not fault-event count; actual events null if unobservable',pagefile_presence_alone_fails=False,OOM_allocator_license_model_mismatch_stop=True,sample_target_seconds=.5,workers=[4,2,1],Threads=1,downgrade_only_on_measured_failure=True,unobservable_metrics_are_null=True,thermal_clock_if_available=True))
    write('DW_THROUGHPUT_PREREGISTRATION.json',dict(PR141_head=BASE_HEAD,scientific_base=BASE,checkpoint_columns=1078,optimize_budget_seconds=900,budget_authority='Union of actual native optimize intervals including sequential RMP warm/cold copy canaries, the mandatory adaptive-smoothing bounded fixture solves and overlapping pricing intervals. Build, postsolve validation, disk I/O, tests recorded separately. Conservative cap reserves; no automatic extension. Explicit crash resume only with worst-case in-flight debit against same900s.',schedule=['DISCOVERY']*5+['CERTIFICATION'],discovery_cap_seconds=20,certification_cap_seconds=60,final_certification_cap_seconds=60,final_reserve_seconds=100,maximum_ordinary_rounds=30,pricing_workers_initial=4,Threads=1,FeasibilityTol=EPS,IntFeasTol=EPS,OptimalityTol=EPS,postsolve_affine_tolerance=POST,negative_threshold=DISCOVERY_RC,no_negative_BestBd=-EPS,full_original_domain=True,no_domain_restrictions=True,column_deletion=False,column_aging=False,dedup='Bit-exact SHA of full raw x/a/c only; Hamming/similarity diagnostic never filters',capture='All distinct negative MIPSOL raw x captured in solver arrival order; final raw X also audited. Outside optimize independently audit every capture; retain first up to4 valid distinct negative trajectories per MESS/call; no ranking/optimum claim and no early stopping.',MAX_COLUMNS_PER_MESS=4,warm_comparison=dict(trigger='Before RMP after first accepted discovery append',pairs=2,order=['cold','warm','warm','cold'],same_RMP_copy=True,cold=dict(Method=2,LPWarmStart=0,Crossover=1),warm=dict(Method=1,LPWarmStart=2,Presolve=-1),native_cap_seconds=60,objective_difference_max=EPS,full_postsolve_required=True,native_basis_acceptance_required=True,median_wall_reduction_gate=.30,fallback='Unchanged PR141 barrier policy'),adaptive_smoothing=dict(enabled=True,mode='adaptive_exponential',initial=.30,minimum=.10,maximum=.80,first_discovery='pi_smooth=pi_true and convexity_smooth=convexity_true; no distortion',update='Use alpha_current in current snapshot; compute d_norm from successive TRUE global coupling dual Linf; d_norm>.50 => next=max(.10,.5*current); .10<d_norm<=.50 => unchanged; <=.10 => next=min(.80,1.25*current). All subsequent RMP snapshots update coupling and convexity duals together, including certification diagnostics; certification pricing uses true snapshot only.',acceptance='full original feasibility and manual smooth RC<=-1e-7 AND manual true RC<=-1e-7, bit-exact dedup only',stagnation='After3 consecutive discovery rounds with zero accepted columns, immediately schedule certification. If four global BestBd do not provide no-negative authority, record SMOOTHING_STAGNATION=true. No domain restriction/fallback.',checkpoint='Save true/smooth dual SHAs and vectors, alpha_current/next, both RCs, candidates, accepted columns, wall, cert bracket; explicit resume preserves smoothing state.',fixture='Full enumeration bounded LP CG with adaptive smoothed discovery plus exact true-dual recovery must match unstabilized/full optimum before first full-domain discovery.',box_proximal_trust_region=False),certificate_authority='Only unstabilized OPTIMAL true RMP pi/alpha and four same-dual full-domain terminal global ObjBound. Exact Fraction global residual correction, fixed1e-8 beta safety and outward rounding unchanged.',certificate_source_SHA=sha(ROOT/'v42_dw_bound/certificate.py'),material_threshold=T_MATERIAL,Arc_root=BASE_LB,old_columns_per_minute=.80998069224726,old_discovery_median=88.07946670003003,old_certification_median=222.48962115001632,performance_gate=dict(actual_4way=True,median_discovery_at_most=35,columns_per_minute_at_least=2,desired_columns_per_minute=3),May_production=[0,0,0],Branch_and_Price=False,production_M1=False,P2_A2_M2=False))
    write('DW_STABILIZATION_PREREGISTRATION.json',dict(mode='adaptive_exponential',enabled_by_user_before_any_optimize=True,policy=read(OUT/'DW_THROUGHPUT_PREREGISTRATION.json')['adaptive_smoothing'],scientific_certificate_uses_true_dual_only=True,box_proximal_trust_region_run=False))
    write('CAMPAIGN_WORKER_POLICY.json',dict(B0_DAY_WORKERS=4,B1_DAY_WORKERS=1,B2_DAY_WORKERS=4,B3_DAY_WORKERS=1,days_per_arm=31,THREADS_PER_SOLVE=1,B2_INNER_PRICING_WORKERS=1,B3_INNER_PRICING_WORKERS='4 if actual four-way resource PASS; else measured2/1',maximum_simultaneous_pricing_processes=4,main_order=['B0','B1','B2','B3(L1)','B3(L2)','B3(L3)','B3(L4)'],B3_loop=['A1','M1','A2','M2'],Actual_feedback_to_Planning=False,next_Planning='previous Planning only',production_calls=[0,0,0]))
    print('THROUGHPUT_PREREG_PASS',len(checks),BASE_HEAD,flush=True)
def freeze():
    sources=sorted((ROOT/'v42_dw_throughput').glob('*.py'))
    names=('DW_THROUGHPUT_PREREGISTRATION.json','DW_RESOURCE_POLICY_V2.json','DW_THROUGHPUT_BASE_AUDIT.json','DW_RMP_BASIS_REUSE_AUDIT.json','DW_STABILIZATION_PREREGISTRATION.json')
    write('EXECUTION_FREEZE.json',dict(sources=[dict(path=p.relative_to(ROOT).as_posix(),sha256=sha(p)) for p in sources],preregistrations={n:sha(OUT/n) for n in names}))
if __name__=='__main__':
    import sys
    freeze() if '--freeze-only' in sys.argv else prepare()
